import{_ as e,o,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const m=JSON.parse('{"title":"FormSearch（搜索表单）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/form/docs/README-FormSearch.md","filePath":"docs/core/src/components/form/docs/README-FormSearch.md"}'),c={name:"docs/core/src/components/form/docs/README-FormSearch.md"};function r(s,t,i,l,n,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="formsearch-搜索表单" tabindex="-1">FormSearch（搜索表单） <a class="header-anchor" href="#formsearch-搜索表单" aria-label="Permalink to &quot;FormSearch（搜索表单）&quot;">​</a></h1><blockquote><p>FormMain 的搜索前缀：自带折叠（maxRows 按真实几何换行）+ 内置操作区（展开更多 / 重置 / 查询），search emit 自动并入静态参数。 范式页：<code>apps/reference/src/pages/menu/showcase/</code>（独立裸用）；ListLayout 内嵌场景见 <code>apps/reference/src/pages/list-layout/guide/</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>空间一等公民是 <code>ListLayout</code> 的搜索侧</strong>：常规列表页 [MUST] 走 <code>ListLayout</code>（内部即「FormSearch + TableMain」组合，搜索侧 props 双子扁平化、<code>staticQuery</code> 提升为直属 prop）——<strong>FormSearch 一般不直接使用</strong></li><li><strong>独立裸用仅当</strong>：纯搜索区页面/组件（无表格，配合外部触发查询）</li><li><strong>何时不用</strong>：普通录入表单用 <code>FormMain</code>；带提交 / 取消操作区的用 <code>FormSubmitPanel</code></li><li>与 FormMain 的差异：<code>rowGutter</code> 默认 14（FormMain 为 8）、<code>layout</code> 默认 <code>{xs:24, sm:12, md:12, lg:8, xl:6}</code>、<code>maxRows</code> 折叠、内置操作区按钮、<code>staticQuery</code> 并入 emit、expose 增 trigger 与折叠控制</li><li>根节点为 WatchSize 包裹的 <code>.form-search</code>，<code>inheritAttrs: false</code>（attrs 显式转发内层 FormMain）</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>最小搜索表单（list / data / @search 即完整）：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">FormSearch</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> @search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;(q: any) =&gt; (query = q)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>@search</code> 载荷 = 表单序列化结果 <code>ExtractFormStringifyFromObject&lt;PO, SO&gt;</code> <strong>并上 <code>staticQuery</code></strong>——静态参数天然并入，无需手工拼接</li><li>折叠（<code>maxRows</code> 默认 2 收起）+ 展开更多 / 重置 / 查询操作区内置默认即生效，零配置</li><li>单项覆盖走具名槽 <code>#&lt;config.key&gt;</code>，scope 是 FormItem 内部 mainProps——<code>v-bind=&quot;scope&quot;</code> 直透给组件即可</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：<code>list</code> + <code>data</code> + <code>@search</code> 即为完整搜索形态</strong>（折叠 + 操作区内置）。以下全部按需开：</li><li><code>staticQuery</code>：默认未设即够用；仅当有非表单静态参数（如固定状态筛选）需并入搜索载荷才设。</li><li><code>maxRows</code>：默认 <code>2</code>（收起折叠）即够用；<code>0</code>=不折叠全展开，仅当搜索项少 / 页面想全显才设。</li><li>具名槽 <code>#&lt;config.key&gt;</code>：默认关（单项由配置驱动）；仅当单项需要完全自定义渲染（复杂组合控件）才开。</li><li><code>compact</code>：默认关；仅当搜索区落入受限窄栏（独立侧栏搜索）才开——窄栏场景优先容器断点系（<code>compact</code> / <code>layoutByContainer</code>），而非给单项 layout 写死 span。</li><li><code>layoutByContainer</code>：默认关；仅当容器断点折叠几何需要切到容器档才开。</li><li>expose <code>triggerSearch()</code> / <code>triggerReset()</code> / <code>toggleCollapse()</code>：默认不需要（操作区按钮内置）；仅当外部需程序化触发（如 ListLayout 列插槽注入）才用。</li><li><strong>AI 填充（trsf36 起默认自动档）</strong>：api 可用（bridge 注册 <code>aiFillApi</code> ∥ <code>aiFillApi</code> prop） 即出悬浮触点；<code>aiFill: false</code> 关（ListLayout 经 <code>formSearchProps</code> 透传）。<code>description</code> prop 描述本搜索面向的业务（如「用户列表的筛选条件」），组件透传时<strong>自报家门</strong>—— 自动拼接「列表筛选条件表单：把用户意图映射为筛选条件字段，未提及的条件留空」形态语义。 填充只落条件值，[MUST NOT] 自动触发搜索（查询仍由用户点）。</li><li><strong>完整能力演示</strong>（staticQuery + 多 slot 覆盖 + 折叠回调）：<code>apps/reference/src/pages/menu/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-泛型-po-解析-so-格式化-sq-静态参数-formsearchprops-po-so-sq-formmainprops-以下" tabindex="-1">Props（泛型 <code>PO</code> 解析 / <code>SO</code> 格式化 / <code>SQ</code> 静态参数，<code>FormSearchProps&lt;PO, SO, SQ&gt;</code> = FormMainProps + 以下） <a class="header-anchor" href="#props-泛型-po-解析-so-格式化-sq-静态参数-formsearchprops-po-so-sq-formmainprops-以下" aria-label="Permalink to &quot;Props（泛型 `PO` 解析 / `SO` 格式化 / `SQ` 静态参数，`FormSearchProps&lt;PO, SO, SQ&gt;` = FormMainProps + 以下）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>FormItemConfigList&lt;PO, SO&gt;</code>（必填）</td><td>—</td><td>同 FormMain，透传</td></tr><tr><td><code>data</code></td><td><code>PO</code>（必填）</td><td>—</td><td>同 FormMain，透传</td></tr><tr><td><code>layout</code></td><td><code>Partial&lt;ColProps&gt;</code></td><td><code>{xs: 24, sm: 12, md: 12, lg: 8, xl: 6}</code></td><td>同 FormMain，默认值不同（搜索三列感）</td></tr><tr><td><code>rowGutter</code></td><td><code>number</code></td><td><code>14</code></td><td>同 FormMain，默认值不同（FormMain 为 8）</td></tr><tr><td><code>layoutScale</code></td><td><code>number</code></td><td><code>1</code></td><td>已声明 prop 不入 attrs 且未显式转发——<strong>实际不传递</strong>（内层 FormMain 恒吃默认 1），消费方传了无效</td></tr><tr><td><code>layoutByContainer</code></td><td><code>boolean</code></td><td><code>false</code></td><td>开启时折叠几何引擎断点源一并切到容器档</td></tr><tr><td><code>labelPosition</code></td><td><code>&quot;right&quot; | &quot;left&quot; | &quot;top&quot;</code></td><td><code>&quot;right&quot;</code></td><td>标签位置</td></tr><tr><td><code>labelWidth</code></td><td><code>string</code></td><td><code>&quot;auto&quot;</code></td><td>标签宽度</td></tr><tr><td><code>staticQuery</code></td><td><code>SQ</code></td><td>未设</td><td>静态参数（非表单非分页），并入搜索 emit 结果</td></tr><tr><td><code>maxRows</code></td><td><code>number</code></td><td><code>2</code></td><td>收起态最多渲染视觉行数（含操作区行），0=不折叠全展开；按真实几何换行计算</td></tr><tr><td><code>compact</code></td><td><code>boolean</code></td><td><code>false</code></td><td>受限窄栏模式：统一单列 span24 + label 置顶，maxRows 仍外部可控</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>search</code></td><td><code>data: ExtractFormStringifyFromObject&lt;PO, SO&gt; &amp; SQ</code>；<code>type: FormSearchSearchType</code></td><td>查询 / 重置 / 单项提交触发（<code>&quot;search&quot;</code> / <code>&quot;reset&quot;</code> / <code>&quot;blur&quot;</code> / <code>&quot;change&quot;</code> / <code>&quot;enter&quot;</code>）</td></tr><tr><td><code>heightChange</code></td><td><code>number</code></td><td>折叠 / 展开容器高度变化</td></tr><tr><td><code>visibleChange</code></td><td><code>boolean</code></td><td>显隐变化</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#&lt;config.key&gt;</code></td><td>FormItem 内部 mainProps</td><td>覆盖搜索单项（透传 FormMain）</td></tr><tr><td><code>#default</code></td><td>—</td><td>⚠️ 被内置操作区按钮（展开更多 / 重置 / 查询）占用，消费方默认插槽不会被转发</td></tr></tbody></table><h3 id="expose-formsearchinstance-po-so-extends-omit-formmaininstance-generate-parse-stringify" tabindex="-1">Expose（<code>FormSearchInstance&lt;PO, SO&gt;</code>，extends <code>Omit&lt;FormMainInstance, &quot;generate&quot; \\| &quot;parse&quot; \\| &quot;stringify&quot;&gt;</code>） <a class="header-anchor" href="#expose-formsearchinstance-po-so-extends-omit-formmaininstance-generate-parse-stringify" aria-label="Permalink to &quot;Expose（`FormSearchInstance&lt;PO, SO&gt;`，extends `Omit&lt;FormMainInstance, &quot;generate&quot; \\| &quot;parse&quot; \\| &quot;stringify&quot;&gt;`）&quot;">​</a></h3><p>继承：<code>validate()</code> / <code>resetFields()</code> / <code>clearValidate(key?)</code>（无三方法——搜索无 round-trip 需求）；新增：<code>triggerSearch()</code> / <code>triggerReset()</code> / <code>toggleCollapse(nextValue?)</code> / <code>isCollapsed: ComputedRef&lt;boolean&gt;</code>。</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>用 <code>#default</code> 插自定义按钮</strong>：默认槽被内置操作区占用，不会渲染——自定义操作走 expose 的 trigger 方法，或交给 ListLayout / 外层编排</li><li><strong><code>@search</code> 后手工再并 staticQuery</strong>：载荷已含静态参数，再拼一次会重复</li><li><strong>class 定向落点</strong>：<code>inheritAttrs: false</code> + attrs 显式转发内层 FormMain——消费方 class 落在内层 ElForm，而非 <code>.form-search</code> 根（WatchSize 包裹）；定向样式按实际落点写选择器</li><li><strong>窄栏场景改 layout 硬撑</strong>：<code>compact</code>（或 <code>layoutByContainer</code>）走容器断点几何，与 ElCol 的视口响应式不同源——窄栏挤崩场景优先容器断点系，而非给单项 layout 写死 span</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>表单族：<code>FormMain</code>（底座，本组件为其搜索前缀）、<code>FormSubmitPanel</code> / <code>FormSubmitBtn</code>（提交面）、<code>FormItemNestForm</code> / <code>FormItemNestFormList</code>（嵌套）</li><li>组合页：<code>ListLayout</code>（内部即「FormSearch + TableMain」，搜索侧 props 双子扁平化；<code>staticQuery</code> 被扁平提升为直属 prop，禁放 formSearchProps 内）</li><li>类型：<code>FormSearchSearchType</code> = <code>&quot;search&quot; \\| &quot;reset&quot; \\| FormItemSubmitType</code>；<code>FormSearchInstance&lt;PO, SO&gt;</code></li><li>范式页：<code>apps/reference/src/pages/menu/showcase/</code>、<code>pages/list-layout/guide/</code></li></ul>',25)])])}const u=e(c,[["render",r]]);export{m as __pageData,u as default};
